import type { Argv, ArgumentsCamelCase, CommandModule } from 'yargs'
import { validateWorkingDir } from '../../util'
import { cwd } from 'process'
import { logger } from '../../logger'
import * as fs from 'fs'
import { Orchestrator, Project } from '@servicenow/sdk-api'
import { NowConfig } from '@servicenow/sdk-build-core'

interface Arguments {
    source: string
}

export const pack: CommandModule<unknown, Arguments> = {
    command: 'pack [source]',
    describe: 'Zip built app into installable artifact',
    builder: (yargs: Argv) => {
        return yargs.positional('source', {
            describe: `Path to the directory that contains package.json configuration`,
            default: cwd(),
            type: 'string',
        })
    },
    handler: async (args: ArgumentsCamelCase<Arguments>): Promise<void> => {
        try {
            const workingDir = validateWorkingDir(args.source)
            logger.info(`Packaging project from "${workingDir}"...`)

            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)

            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger })

            const orchestrator = new Orchestrator(project)

            const packPath = await orchestrator.pack()

            logger.info(`Single artifact emitted as "${packPath}".`)
        } catch (e) {
            logger.error(e)
        }
    },
}
